-- ---------------------------------------------------------------------
-- returns-inspection.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO returns: 3-day seller inspection, then automatic refund
-- Run once in Supabase → SQL Editor, AFTER returns.sql. Safe to re-run.
--
--   1. The customer sends the item back (status "returning").
--   2. The seller marks the parcel arrived → status "received" and a 3-day
--      inspection window starts. If the seller never marks it, it counts as
--      arrived 7 days after the customer sent it.
--   3. Within those 3 days the seller can confirm it's fine (refund now) or
--      report a problem (MIVO reviews). With no reply, the refund goes out
--      automatically when the window ends (daily job).
-- =====================================================================

begin;

alter table public.return_requests add column if not exists shipped_back_at timestamptz;
alter table public.return_requests add column if not exists received_at timestamptz;
alter table public.return_requests add column if not exists inspect_by timestamptz;

-- Remember when the customer sent the item back.
create or replace function public.mivo_return_shipped_back()
returns trigger language plpgsql as $$
begin
  if new.status = 'returning' and (tg_op = 'INSERT' or old.status is distinct from 'returning') then
    new.shipped_back_at := coalesce(new.shipped_back_at, now());
  end if;
  return new;
end;
$$;
drop trigger if exists mivo_return_shipped_back on public.return_requests;
create trigger mivo_return_shipped_back before insert or update of status on public.return_requests
for each row execute function public.mivo_return_shipped_back();

-- Seller: the returned parcel has arrived; start the 3-day inspection.
create or replace function public.return_request_seller_arrived(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype;
begin
  select * into r from public.return_requests where id = p_id for update;
  if not found then raise exception 'Request not found'; end if;
  if not public.mivo_can_manage_shop(r.seller_id) then raise exception 'Not allowed'; end if;
  if r.status not in ('returning', 'approved_return') then raise exception 'This request is already %', r.status; end if;
  update public.return_requests
     set status = 'received', received_at = now(), inspect_by = now() + interval '3 days', updated_at = now()
   where id = r.id;
  perform public.mivo_return_log(r.id, 'seller', 'arrived', 'Parcel arrived; 3-day inspection started', null);
end;
$$;

-- Seller: item is fine (refund) or has a problem (MIVO review). Also allowed
-- during the inspection window ("received").
create or replace function public.return_request_seller_received(p_id uuid, p_ok boolean, p_amount numeric, p_note text)
returns void language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype;
begin
  select * into r from public.return_requests where id = p_id for update;
  if not found then raise exception 'Request not found'; end if;
  if not public.mivo_can_manage_shop(r.seller_id) then raise exception 'Not allowed'; end if;
  if r.status not in ('returning', 'approved_return', 'received') then raise exception 'This request is already %', r.status; end if;

  if p_ok then
    update public.return_requests set status = 'refunding', final_amount = requested_amount,
           received_at = coalesce(received_at, now()),
           seller_note = coalesce(nullif(btrim(p_note), ''), seller_note), updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'seller', 'received_ok', p_note, r.requested_amount);
  else
    if p_amount is null or p_amount < 0 or p_amount >= r.requested_amount then
      raise exception 'Enter the amount you think should be refunded (less than RM%)', r.requested_amount;
    end if;
    if coalesce(btrim(p_note), '') = '' then raise exception 'Explain what is wrong with the returned item'; end if;
    update public.return_requests set status = 'mivo_review', seller_amount = round(p_amount, 2),
           received_at = coalesce(received_at, now()),
           dispute_note = btrim(p_note), updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'seller', 'received_issue', p_note, round(p_amount, 2));
  end if;
end;
$$;

-- Daily job (called by /api/cron/capture-holds).
create or replace function public.return_requests_auto()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_accepted int := 0; v_closed int := 0; v_arrived int := 0; v_refund int := 0; r record;
begin
  for r in select id, requested_amount, needs_return from public.return_requests
            where status = 'requested' and respond_by < now() loop
    update public.return_requests
       set status = case when r.needs_return then 'approved_return' else 'refunding' end,
           final_amount = case when r.needs_return then null else r.requested_amount end,
           ship_back_by = case when r.needs_return then now() + interval '7 days' end, updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'system', 'auto_accepted', 'Seller did not respond within 2 days', r.requested_amount);
    v_accepted := v_accepted + 1;
  end loop;

  for r in select id from public.return_requests
            where status = 'approved_return' and ship_back_by < now() and return_tracking is null loop
    update public.return_requests set status = 'closed', updated_at = now() where id = r.id;
    perform public.mivo_return_log(r.id, 'system', 'auto_closed', 'Item was not sent back within 7 days', null);
    v_closed := v_closed + 1;
  end loop;

  -- Sent back 7+ days ago and the seller never marked it arrived: start the inspection.
  for r in select id from public.return_requests
            where status = 'returning' and coalesce(shipped_back_at, updated_at) < now() - interval '7 days' loop
    update public.return_requests
       set status = 'received', received_at = now(), inspect_by = now() + interval '3 days', updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'system', 'arrived', 'Treated as arrived 7 days after it was sent back; 3-day inspection started', null);
    v_arrived := v_arrived + 1;
  end loop;

  -- Inspection over without a dispute: approve the refund (paid out by the same job).
  for r in select id, requested_amount from public.return_requests
            where status = 'received' and inspect_by < now() loop
    update public.return_requests
       set status = 'refunding', final_amount = requested_amount, updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'system', 'auto_refund', 'No problem reported within 3 days of arrival', r.requested_amount);
    v_refund := v_refund + 1;
  end loop;

  return jsonb_build_object('auto_accepted', v_accepted, 'auto_closed', v_closed,
                            'auto_arrived', v_arrived, 'auto_refund', v_refund);
end;
$$;

revoke all on function public.return_requests_auto() from public, anon, authenticated;
revoke all on function public.return_request_seller_arrived(uuid) from public, anon;
grant execute on function public.return_request_seller_arrived(uuid) to authenticated;
grant execute on function public.return_request_seller_received(uuid, boolean, numeric, text) to authenticated;

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- warranty-resolution.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO warranty: what happens after a claim is approved
-- Run once in Supabase → SQL Editor. Safe to re-run.
--
-- MIVO picks how to resolve an approved claim:
--   replace  – send a new part      repair – fix and send it back
--   refund   – refund through Stripe (up to what was paid for the item)
-- and whether the customer must send the faulty part back first.
--
-- Stages (warranty_claims.resolution_stage):
--   awaiting_return → returning → (MIVO receives it) →
--     to_ship → shipped → done          (replace / repair)
--     refund_pending → refunded         (refund)
-- Every step is logged in warranty_claim_events and shown to both sides.
-- =====================================================================

begin;

alter table public.warranty_claims add column if not exists resolution_type text;
alter table public.warranty_claims add column if not exists resolution_stage text;
alter table public.warranty_claims add column if not exists needs_return boolean not null default false;
alter table public.warranty_claims add column if not exists return_courier text;
alter table public.warranty_claims add column if not exists return_tracking text;
alter table public.warranty_claims add column if not exists returned_at timestamptz;
alter table public.warranty_claims add column if not exists item_received_at timestamptz;
alter table public.warranty_claims add column if not exists replacement_courier text;
alter table public.warranty_claims add column if not exists replacement_tracking text;
alter table public.warranty_claims add column if not exists replacement_shipped_at timestamptz;
alter table public.warranty_claims add column if not exists refund_amount numeric(12,2);
alter table public.warranty_claims add column if not exists stripe_refund_id text;
alter table public.warranty_claims add column if not exists refunded_at timestamptz;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'warranty_claims_resolution_type_check') then
    alter table public.warranty_claims add constraint warranty_claims_resolution_type_check
      check (resolution_type is null or resolution_type in ('replace', 'repair', 'refund'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'warranty_claims_resolution_stage_check') then
    alter table public.warranty_claims add constraint warranty_claims_resolution_stage_check
      check (resolution_stage is null or resolution_stage in
        ('awaiting_return', 'returning', 'to_ship', 'shipped', 'refund_pending', 'refunded', 'done'));
  end if;
end;
$$;

create table if not exists public.warranty_claim_events (
  id uuid primary key default gen_random_uuid(),
  claim_id uuid not null references public.warranty_claims(id) on delete cascade,
  actor text not null,            -- customer | mivo | system
  action text not null,
  note text,
  created_at timestamptz not null default now()
);
create index if not exists warranty_claim_events_claim on public.warranty_claim_events (claim_id, created_at);
alter table public.warranty_claim_events enable row level security;
revoke all on public.warranty_claim_events from anon, authenticated;
grant select on public.warranty_claim_events to authenticated;
drop policy if exists "warranty events: owner or admin" on public.warranty_claim_events;
create policy "warranty events: owner or admin" on public.warranty_claim_events for select to authenticated
  using (public.is_admin() or exists (select 1 from public.warranty_claims c where c.id = claim_id and c.user_id = auth.uid()));

create or replace function public.mivo_warranty_log(p_claim uuid, p_actor text, p_action text, p_note text)
returns void language sql security definer set search_path = public as $$
  insert into public.warranty_claim_events (claim_id, actor, action, note)
  values (p_claim, p_actor, p_action, nullif(btrim(coalesce(p_note, '')), ''));
$$;

-- MIVO: choose how an approved claim is resolved.
create or replace function public.admin_warranty_set_resolution(
  p_claim_id uuid, p_type text, p_needs_return boolean, p_refund_amount numeric, p_note text
)
returns void language plpgsql security definer set search_path = public as $$
declare c public.warranty_claims%rowtype; v_paid numeric;
begin
  if not public.is_admin() then raise exception 'Only MIVO can resolve warranty claims'; end if;
  select * into c from public.warranty_claims where id = p_claim_id for update;
  if not found then raise exception 'Claim not found'; end if;
  if c.status not in ('approved', 'reviewing', 'new') then raise exception 'This claim is already %', c.status; end if;
  if p_type not in ('replace', 'repair', 'refund') then raise exception 'Choose replace, repair or refund'; end if;
  if c.resolution_stage in ('shipped', 'refunded', 'done') then raise exception 'This claim is already resolved'; end if;

  if p_type = 'refund' then
    select coalesce(line_subtotal, unit_price * quantity) into v_paid from public.order_items where id = c.order_item_id;
    if p_refund_amount is null or p_refund_amount <= 0 then raise exception 'Enter the refund amount'; end if;
    if v_paid is not null and p_refund_amount > v_paid then
      raise exception 'The refund can''t be more than the customer paid for this item (RM%)', v_paid;
    end if;
  end if;

  update public.warranty_claims
     set status = 'approved',
         resolution_type = p_type,
         needs_return = coalesce(p_needs_return, false),
         refund_amount = case when p_type = 'refund' then round(p_refund_amount, 2) end,
         resolution_stage = case
           when coalesce(p_needs_return, false) then 'awaiting_return'
           when p_type = 'refund' then 'refund_pending'
           else 'to_ship' end,
         resolution_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), resolution_note),
         reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
   where id = c.id;
  perform public.mivo_warranty_log(c.id, 'mivo', 'resolution_' || p_type, p_note);
end;
$$;

-- Customer: the faulty part is on its way back.
create or replace function public.warranty_customer_ship_back(p_claim_id uuid, p_courier text, p_tracking text)
returns void language plpgsql security definer set search_path = public as $$
declare c public.warranty_claims%rowtype;
begin
  select * into c from public.warranty_claims where id = p_claim_id for update;
  if not found or c.user_id <> auth.uid() then raise exception 'Claim not found'; end if;
  if c.resolution_stage is distinct from 'awaiting_return' then raise exception 'Nothing to send back for this claim'; end if;
  if coalesce(btrim(p_courier), '') = '' or coalesce(btrim(p_tracking), '') = '' then
    raise exception 'Enter the courier and tracking number';
  end if;
  update public.warranty_claims
     set resolution_stage = 'returning', return_courier = btrim(p_courier), return_tracking = btrim(p_tracking),
         returned_at = now(), updated_at = now()
   where id = c.id;
  perform public.mivo_warranty_log(c.id, 'customer', 'shipped_back', btrim(p_courier) || ' ' || btrim(p_tracking));
end;
$$;

-- MIVO: the faulty part has arrived.
create or replace function public.admin_warranty_item_received(p_claim_id uuid, p_note text)
returns void language plpgsql security definer set search_path = public as $$
declare c public.warranty_claims%rowtype;
begin
  if not public.is_admin() then raise exception 'Only MIVO can update warranty claims'; end if;
  select * into c from public.warranty_claims where id = p_claim_id for update;
  if not found then raise exception 'Claim not found'; end if;
  if c.resolution_stage not in ('awaiting_return', 'returning') then raise exception 'This claim is not waiting for the item'; end if;
  update public.warranty_claims
     set resolution_stage = case when c.resolution_type = 'refund' then 'refund_pending' else 'to_ship' end,
         item_received_at = now(), updated_at = now()
   where id = c.id;
  perform public.mivo_warranty_log(c.id, 'mivo', 'item_received', p_note);
end;
$$;

-- MIVO: the replacement (or repaired part) is on its way to the customer.
create or replace function public.admin_warranty_ship_replacement(p_claim_id uuid, p_courier text, p_tracking text)
returns void language plpgsql security definer set search_path = public as $$
declare c public.warranty_claims%rowtype;
begin
  if not public.is_admin() then raise exception 'Only MIVO can update warranty claims'; end if;
  select * into c from public.warranty_claims where id = p_claim_id for update;
  if not found then raise exception 'Claim not found'; end if;
  if c.resolution_stage is distinct from 'to_ship' then raise exception 'This claim has nothing to ship yet'; end if;
  if coalesce(btrim(p_courier), '') = '' or coalesce(btrim(p_tracking), '') = '' then
    raise exception 'Enter the courier and tracking number';
  end if;
  update public.warranty_claims
     set resolution_stage = 'shipped', replacement_courier = btrim(p_courier),
         replacement_tracking = btrim(p_tracking), replacement_shipped_at = now(), updated_at = now()
   where id = c.id;
  perform public.mivo_warranty_log(c.id, 'mivo', 'replacement_shipped', btrim(p_courier) || ' ' || btrim(p_tracking));
end;
$$;

-- Customer: the replacement / repaired part arrived. Claim complete.
create or replace function public.warranty_customer_confirm(p_claim_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare c public.warranty_claims%rowtype;
begin
  select * into c from public.warranty_claims where id = p_claim_id for update;
  if not found or c.user_id <> auth.uid() then raise exception 'Claim not found'; end if;
  if c.resolution_stage is distinct from 'shipped' then raise exception 'Nothing to confirm yet'; end if;
  update public.warranty_claims
     set resolution_stage = 'done', status = 'completed', updated_at = now()
   where id = c.id;
  perform public.mivo_warranty_log(c.id, 'customer', 'received', null);
end;
$$;

revoke all on function public.mivo_warranty_log(uuid, text, text, text) from public, anon, authenticated;
revoke all on function public.admin_warranty_set_resolution(uuid, text, boolean, numeric, text) from public, anon;
revoke all on function public.warranty_customer_ship_back(uuid, text, text) from public, anon;
revoke all on function public.admin_warranty_item_received(uuid, text) from public, anon;
revoke all on function public.admin_warranty_ship_replacement(uuid, text, text) from public, anon;
revoke all on function public.warranty_customer_confirm(uuid) from public, anon;
grant execute on function public.admin_warranty_set_resolution(uuid, text, boolean, numeric, text) to authenticated;
grant execute on function public.warranty_customer_ship_back(uuid, text, text) to authenticated;
grant execute on function public.admin_warranty_item_received(uuid, text) to authenticated;
grant execute on function public.admin_warranty_ship_replacement(uuid, text, text) to authenticated;
grant execute on function public.warranty_customer_confirm(uuid) to authenticated;

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- review-names.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO reviews: anonymous (masked name) or public (real name)
-- Run once in Supabase → SQL Editor. Safe to re-run.
--
-- The customer chooses when rating an order. Anonymous reviews show a
-- masked name like "A****r"; public ones show the customer's name.
-- Reviews written before this show masked names.
-- =====================================================================

begin;

alter table public.product_reviews add column if not exists is_anonymous boolean not null default true;

create or replace function public.mivo_mask_name(p_name text)
returns text language sql immutable as $$
  select case
    when p_name is null or btrim(p_name) = '' then null
    when char_length(btrim(p_name)) <= 2 then left(btrim(p_name), 1) || '*'
    else left(btrim(p_name), 1) || repeat('*', least(char_length(btrim(p_name)) - 2, 4)) || right(btrim(p_name), 1)
  end;
$$;

-- Display names for published reviews. Never returns emails.
create or replace function public.product_review_names(p_ids uuid[])
returns table (id uuid, display_name text, is_anonymous boolean)
language sql stable security definer set search_path = public as $$
  select r.id,
         case when r.is_anonymous
              then coalesce(public.mivo_mask_name(coalesce(nullif(btrim(p.full_name), ''), split_part(u.email, '@', 1))), 'MIVO customer')
              else coalesce(nullif(btrim(p.full_name), ''), public.mivo_mask_name(split_part(u.email, '@', 1)), 'MIVO customer')
         end,
         r.is_anonymous
    from public.product_reviews r
    left join public.profiles p on p.id = r.user_id
    left join auth.users u on u.id = r.user_id
   where r.id = any(coalesce(p_ids, '{}'))
     and coalesce(r.is_hidden, false) = false;
$$;

revoke all on function public.product_review_names(uuid[]) from public;
grant execute on function public.product_review_names(uuid[]) to anon, authenticated;

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- easyparcel.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO × EasyParcel (Open API): connection tokens and shipment labels
-- Run once in Supabase → SQL Editor, AFTER checkout-per-shop.sql. Safe to re-run.
-- =====================================================================

begin;

-- One row: MIVO's linked EasyParcel account. Server-only (service role):
-- no policies, so the website's public/anon and signed-in roles can't read tokens.
create table if not exists public.easyparcel_connection (
  id int primary key default 1 check (id = 1),
  access_token text not null,
  refresh_token text,
  expires_at timestamptz,
  refresh_expires_at timestamptz,
  connected_by uuid references auth.users(id) on delete set null,
  connected_at timestamptz,
  updated_at timestamptz not null default now()
);
alter table public.easyparcel_connection enable row level security;
revoke all on public.easyparcel_connection from anon, authenticated;

-- EasyParcel booking details on each shop parcel's shipment.
alter table public.shipments add column if not exists provider text;              -- 'easyparcel' | null (manual)
alter table public.shipments add column if not exists ep_shipment_number text;    -- ES-YYMM-XXXXX
alter table public.shipments add column if not exists ep_order_number text;       -- EI-YYMM-XXXXX
alter table public.shipments add column if not exists ep_service_id text;
alter table public.shipments add column if not exists ep_service_name text;
alter table public.shipments add column if not exists ep_paid_amount numeric(12,2);
alter table public.shipments add column if not exists awb_url text;
alter table public.shipments add column if not exists label_urls jsonb;
alter table public.shipments add column if not exists collection_method text;    -- pickup | dropoff
alter table public.shipments add column if not exists tracking_status_code int;
alter table public.shipments add column if not exists tracking_status text;
alter table public.shipments add column if not exists tracking_checked_at timestamptz;
create unique index if not exists shipments_ep_shipment_number on public.shipments (ep_shipment_number)
  where ep_shipment_number is not null;

-- Courier scan history for the animated tracker.
create table if not exists public.shipment_tracking_events (
  id bigint generated always as identity primary key,
  shipment_id uuid not null references public.shipments(id) on delete cascade,
  status_code int,
  description text not null,
  location text,
  event_time timestamptz not null,
  created_at timestamptz not null default now(),
  unique (shipment_id, event_time, description)
);
alter table public.shipment_tracking_events enable row level security;
revoke all on public.shipment_tracking_events from anon, authenticated;
grant select on public.shipment_tracking_events to authenticated;
drop policy if exists "tracking events: buyer, shop or admin" on public.shipment_tracking_events;
create policy "tracking events: buyer, shop or admin" on public.shipment_tracking_events for select to authenticated
  using (exists (
    select 1 from public.shipments sh
      join public.seller_orders so on so.id = sh.seller_order_id
      join public.orders o on o.id = so.order_id
     where sh.id = shipment_id
       and (o.user_id = auth.uid() or public.mivo_can_manage_shop(so.seller_id))
  ));

-- Each shop's pickup (sender) address for couriers. Read and written through
-- the functions below; prefilled from the approved seller application.
alter table public.sellers add column if not exists pickup_address jsonb;
do $$
begin
  if to_regclass('public.seller_applications') is not null then
    update public.sellers s
       set pickup_address = a.pickup_address
      from public.seller_applications a
     where a.seller_id = s.id and a.status = 'approved'
       and s.pickup_address is null and a.pickup_address is not null;
  end if;
end;
$$;

create or replace function public.shop_pickup_address(p_seller_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.mivo_can_manage_shop(p_seller_id) then raise exception 'Not allowed'; end if;
  return (select pickup_address from public.sellers where id = p_seller_id);
end;
$$;

create or replace function public.shop_save_pickup_address(p_seller_id uuid, p_address jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.mivo_can_manage_shop(p_seller_id) then raise exception 'Not allowed'; end if;
  if coalesce(btrim(p_address ->> 'name'), '') = '' or coalesce(btrim(p_address ->> 'phone'), '') = ''
     or coalesce(btrim(p_address ->> 'line'), '') = '' or coalesce(p_address ->> 'postcode', '') !~ '^\d{5}$'
     or coalesce(btrim(p_address ->> 'city'), '') = '' or coalesce(btrim(p_address ->> 'state'), '') = '' then
    raise exception 'Fill in name, phone, street, 5-digit postcode, city and state';
  end if;
  update public.sellers set pickup_address = p_address, updated_at = now() where id = p_seller_id;
end;
$$;

revoke all on function public.shop_pickup_address(uuid) from public, anon;
revoke all on function public.shop_save_pickup_address(uuid, jsonb) from public, anon;
grant execute on function public.shop_pickup_address(uuid) to authenticated;
grant execute on function public.shop_save_pickup_address(uuid, jsonb) to authenticated;

-- Server only: mark a shop parcel shipped once EasyParcel has issued the AWB
-- (from the booking route, the webhook or the daily job). Runs the normal
-- per-shop fulfilment as the shop's owner so all its rules still apply.
create or replace function public.mivo_system_ship_parcel(
  p_seller_order_id uuid, p_courier text, p_tracking text, p_tracking_url text
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_owner uuid; v_result jsonb;
begin
  select s.owner_id into v_owner
    from public.seller_orders so join public.sellers s on s.id = so.seller_id
   where so.id = p_seller_order_id;
  if v_owner is null then raise exception 'Shop has no owner'; end if;
  perform set_config('request.jwt.claims', json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_owner::text, true);
  v_result := public.admin_update_shop_fulfilment(p_seller_order_id, 'shipped', p_courier, p_tracking, p_tracking_url);
  return v_result;
end;
$$;
revoke all on function public.mivo_system_ship_parcel(uuid, text, text, text) from public, anon, authenticated;
grant execute on function public.mivo_system_ship_parcel(uuid, text, text, text) to service_role;

-- Short-lived cache of EasyParcel rates (same route, weight and size) so
-- checkout stays within EasyParcel's quotation limits. Server only.
create table if not exists public.easyparcel_rate_cache (
  cache_key text primary key,
  quotes jsonb not null,
  expires_at timestamptz not null
);
alter table public.easyparcel_rate_cache enable row level security;
revoke all on public.easyparcel_rate_cache from anon, authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- platform.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO platform tools (superadmin): notices to sellers, commission
-- changes, platform campaigns with subsidies.
-- Run once in Supabase → SQL Editor, AFTER superadmin.sql and
-- seller-centre.sql. Safe to re-run.
--
-- Campaign money works on top of the existing voucher system:
--   * A platform campaign is linked to a voucher code customers use.
--   * funding = 'platform': MIVO pays the whole discount. Optionally a
--     temporary commission increase applies to sellers during the
--     campaign (sellers are notified automatically).
--   * funding = 'shared': sellers are invited (notice) and accept or
--     reject. Accepted sellers pay their share of the discount on their
--     items; MIVO pays the rest, and the whole discount for shops that
--     did not accept.
-- Commission changes: scheduled (from a date) or temporary (from–until),
-- for all shops or chosen shops; every change sends a notice. The daily
-- cron applies and reverts them (see /api/cron/capture-holds).
-- =====================================================================

begin;

-- ----------------------------------------------------------------- notices
create table if not exists public.platform_notices (
  id uuid primary key default gen_random_uuid(),
  kind text not null default 'info' check (kind in ('info','campaign_invite','commission_change')),
  title text not null,
  body text not null,
  seller_ids uuid[],                       -- null = every shop
  campaign_id uuid,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create table if not exists public.platform_notice_reads (
  notice_id uuid not null references public.platform_notices(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  read_at timestamptz not null default now(),
  primary key (notice_id, user_id)
);
alter table public.platform_notices enable row level security;
alter table public.platform_notice_reads enable row level security;
revoke all on public.platform_notices, public.platform_notice_reads from anon, authenticated;

-- ----------------------------------------------------------- commission
create table if not exists public.commission_changes (
  id uuid primary key default gen_random_uuid(),
  seller_ids uuid[],                       -- null = every approved shop (except MIVO Direct)
  rate numeric(5,2) not null check (rate >= 0 and rate <= 50),
  starts_at timestamptz not null,
  ends_at timestamptz,                     -- null = permanent
  reason text,
  campaign_id uuid,
  status text not null default 'scheduled' check (status in ('scheduled','active','done','cancelled')),
  previous_rates jsonb,                    -- {seller_id: old_rate} captured when applied
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.commission_changes enable row level security;
revoke all on public.commission_changes from anon, authenticated;

-- ------------------------------------------------------------ campaigns
create table if not exists public.platform_campaigns (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  description text,
  voucher_code text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  funding text not null check (funding in ('platform','shared')),
  platform_share_pct numeric(5,2) not null default 100 check (platform_share_pct between 0 and 100),
  commission_bump_rate numeric(5,2),       -- temporary commission during the campaign (platform-funded only)
  status text not null default 'active' check (status in ('active','cancelled')),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check (ends_at > starts_at)
);
create table if not exists public.campaign_participants (
  campaign_id uuid not null references public.platform_campaigns(id) on delete cascade,
  seller_id uuid not null references public.sellers(id) on delete cascade,
  status text not null default 'invited' check (status in ('invited','accepted','rejected')),
  responded_at timestamptz,
  responded_by uuid references auth.users(id) on delete set null,
  primary key (campaign_id, seller_id)
);
alter table public.platform_campaigns enable row level security;
alter table public.campaign_participants enable row level security;
revoke all on public.platform_campaigns, public.campaign_participants from anon, authenticated;

-- ============================================================ functions
create or replace function public.mivo_require_superadmin()
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_superadmin() then raise exception 'Only the MIVO superadmin can do this'; end if;
end;
$$;

-- Send a notice (superadmin). seller_ids null = all shops.
create or replace function public.platform_send_notice(
  p_title text, p_body text, p_seller_ids uuid[] default null, p_kind text default 'info', p_campaign_id uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  perform public.mivo_require_superadmin();
  if coalesce(btrim(p_title), '') = '' or coalesce(btrim(p_body), '') = '' then
    raise exception 'Title and message are required';
  end if;
  insert into public.platform_notices (kind, title, body, seller_ids, campaign_id, created_by)
  values (coalesce(p_kind, 'info'), btrim(p_title), btrim(p_body),
          case when p_seller_ids is null or cardinality(p_seller_ids) = 0 then null else p_seller_ids end,
          p_campaign_id, auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

-- Superadmin: sent notices with how many shop owners read them.
create or replace function public.platform_notices_sent()
returns table (id uuid, kind text, title text, body text, seller_ids uuid[], created_at timestamptz, reads bigint)
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.mivo_require_superadmin();
  return query
    select n.id, n.kind, n.title, n.body, n.seller_ids, n.created_at,
           (select count(*) from public.platform_notice_reads r where r.notice_id = n.id)
      from public.platform_notices n order by n.created_at desc limit 300;
end;
$$;

-- Seller: notices for any of my shops, with read state and campaign invite state.
create or replace function public.seller_notices()
returns table (id uuid, kind text, title text, body text, campaign_id uuid, created_at timestamptz,
               is_read boolean, invites jsonb)
language sql stable security definer set search_path = public as $$
  select n.id, n.kind, n.title, n.body, n.campaign_id, n.created_at,
         exists (select 1 from public.platform_notice_reads r where r.notice_id = n.id and r.user_id = auth.uid()),
         (select coalesce(jsonb_agg(jsonb_build_object('seller_id', p.seller_id, 'shop', s.shop_name, 'status', p.status)), '[]'::jsonb)
            from public.campaign_participants p join public.sellers s on s.id = p.seller_id
           where p.campaign_id = n.campaign_id and s.owner_id = auth.uid())
    from public.platform_notices n
   where exists (select 1 from public.sellers s where s.owner_id = auth.uid() and s.status = 'approved'
                   and (n.seller_ids is null or s.id = any(n.seller_ids)))
   order by n.created_at desc
   limit 200;
$$;

create or replace function public.seller_unread_notices()
returns integer language sql stable security definer set search_path = public as $$
  select count(*)::int from public.seller_notices() where not is_read;
$$;

create or replace function public.seller_mark_notice_read(p_notice_id uuid)
returns void language sql security definer set search_path = public as $$
  insert into public.platform_notice_reads (notice_id, user_id) values (p_notice_id, auth.uid())
  on conflict do nothing;
$$;

-- ---------------------------------------------------------- commission
create or replace function public.platform_schedule_commission(
  p_seller_ids uuid[], p_rate numeric, p_starts_at timestamptz, p_ends_at timestamptz,
  p_reason text, p_campaign_id uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_scope text; v_when text;
begin
  perform public.mivo_require_superadmin();
  if p_rate is null or p_rate < 0 or p_rate > 50 then raise exception 'Commission must be between 0%% and 50%%'; end if;
  if p_starts_at is null then raise exception 'Choose when the change starts'; end if;
  if p_ends_at is not null and p_ends_at <= p_starts_at then raise exception 'End must be after start'; end if;

  insert into public.commission_changes (seller_ids, rate, starts_at, ends_at, reason, campaign_id, created_by)
  values (case when p_seller_ids is null or cardinality(p_seller_ids) = 0 then null else p_seller_ids end,
          round(p_rate, 2), p_starts_at, p_ends_at, nullif(btrim(coalesce(p_reason, '')), ''), p_campaign_id, auth.uid())
  returning id into v_id;

  v_scope := case when p_seller_ids is null or cardinality(p_seller_ids) = 0 then 'all shops' else 'your shop' end;
  v_when := 'from ' || to_char(p_starts_at at time zone 'Asia/Kuala_Lumpur', 'DD Mon YYYY HH24:MI')
         || coalesce(' until ' || to_char(p_ends_at at time zone 'Asia/Kuala_Lumpur', 'DD Mon YYYY HH24:MI')
                     || ' (then back to the previous rate)', '');
  perform public.platform_send_notice(
    'Commission change: ' || round(p_rate, 2) || '%',
    'MIVO commission for ' || v_scope || ' will be ' || round(p_rate, 2) || '% ' || v_when || '.'
      || coalesce(E'\n\nReason: ' || nullif(btrim(coalesce(p_reason, '')), ''), ''),
    p_seller_ids, 'commission_change', p_campaign_id);
  return v_id;
end;
$$;

create or replace function public.platform_cancel_commission(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare c public.commission_changes%rowtype;
begin
  perform public.mivo_require_superadmin();
  select * into c from public.commission_changes where id = p_id for update;
  if not found then raise exception 'Not found'; end if;
  if c.status = 'scheduled' then
    update public.commission_changes set status = 'cancelled' where id = p_id;
    perform public.platform_send_notice('Commission change cancelled',
      'The commission change to ' || c.rate || '% scheduled for '
      || to_char(c.starts_at at time zone 'Asia/Kuala_Lumpur', 'DD Mon YYYY') || ' has been cancelled.',
      c.seller_ids, 'commission_change', c.campaign_id);
  elsif c.status = 'active' then
    -- End it now: the next apply run restores previous rates.
    update public.commission_changes set ends_at = now() where id = p_id;
  else
    raise exception 'This change is already %', c.status;
  end if;
end;
$$;

-- Applies due changes and reverts finished temporary ones. Called by the
-- daily cron (service role) and by the superadmin's "apply now".
create or replace function public.mivo_apply_commission_changes()
returns jsonb language plpgsql security definer set search_path = public as $$
declare c record; v_prev jsonb; v_applied int := 0; v_reverted int := 0;
begin
  if auth.uid() is not null and not public.is_superadmin() then raise exception 'Not allowed'; end if;

  for c in select * from public.commission_changes
            where status = 'scheduled' and starts_at <= now() order by starts_at for update loop
    select coalesce(jsonb_object_agg(id::text, commission_rate), '{}'::jsonb) into v_prev
      from public.sellers
     where status = 'approved' and coalesce(tier, 'standard') <> 'direct'
       and (c.seller_ids is null or id = any(c.seller_ids));
    update public.sellers set commission_rate = c.rate, updated_at = now()
     where status = 'approved' and coalesce(tier, 'standard') <> 'direct'
       and (c.seller_ids is null or id = any(c.seller_ids));
    update public.commission_changes
       set status = case when ends_at is null then 'done' else 'active' end, previous_rates = v_prev
     where id = c.id;
    v_applied := v_applied + 1;
  end loop;

  for c in select * from public.commission_changes
            where status = 'active' and ends_at is not null and ends_at <= now() for update loop
    update public.sellers s set commission_rate = (c.previous_rates ->> s.id::text)::numeric, updated_at = now()
     where c.previous_rates ? s.id::text;
    update public.commission_changes set status = 'done' where id = c.id;
    v_reverted := v_reverted + 1;
  end loop;

  return jsonb_build_object('applied', v_applied, 'reverted', v_reverted);
end;
$$;

create or replace function public.platform_commission_overview()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.mivo_require_superadmin();
  return jsonb_build_object(
    'shops', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'shop_name', shop_name, 'tier', tier,
                       'status', status, 'commission_rate', commission_rate) order by shop_name), '[]'::jsonb)
                from public.sellers),
    'changes', (select coalesce(jsonb_agg(to_jsonb(c) order by c.created_at desc), '[]'::jsonb)
                  from (select * from public.commission_changes order by created_at desc limit 200) c));
end;
$$;

-- ----------------------------------------------------------- campaigns
create or replace function public.platform_create_campaign(
  p_name text, p_description text, p_voucher_code text, p_starts_at timestamptz, p_ends_at timestamptz,
  p_funding text, p_platform_share_pct numeric, p_commission_bump_rate numeric, p_seller_ids uuid[] default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_share numeric; v_invited uuid[];
begin
  perform public.mivo_require_superadmin();
  if coalesce(btrim(p_name), '') = '' or coalesce(btrim(p_voucher_code), '') = '' then
    raise exception 'Name and voucher code are required';
  end if;
  if p_funding not in ('platform','shared') then raise exception 'Choose who pays'; end if;
  v_share := case when p_funding = 'platform' then 100 else coalesce(p_platform_share_pct, 50) end;
  if v_share < 0 or v_share >= 100 and p_funding = 'shared' then
    raise exception 'For a shared campaign, MIVO''s share must be below 100%%';
  end if;

  insert into public.platform_campaigns (name, description, voucher_code, starts_at, ends_at, funding,
                                         platform_share_pct, commission_bump_rate, created_by)
  values (btrim(p_name), nullif(btrim(coalesce(p_description, '')), ''), upper(btrim(p_voucher_code)),
          p_starts_at, p_ends_at, p_funding, v_share,
          case when p_funding = 'platform' then p_commission_bump_rate end, auth.uid())
  returning id into v_id;

  if p_funding = 'shared' then
    insert into public.campaign_participants (campaign_id, seller_id)
    select v_id, s.id from public.sellers s
     where s.status = 'approved' and coalesce(s.tier, 'standard') <> 'direct'
       and (p_seller_ids is null or cardinality(p_seller_ids) = 0 or s.id = any(p_seller_ids))
    on conflict do nothing;
    select array_agg(seller_id) into v_invited from public.campaign_participants where campaign_id = v_id;
    perform public.platform_send_notice(
      'Join campaign: ' || btrim(p_name),
      coalesce(nullif(btrim(coalesce(p_description, '')), '') || E'\n\n', '')
        || 'Voucher ' || upper(btrim(p_voucher_code)) || ', '
        || to_char(p_starts_at at time zone 'Asia/Kuala_Lumpur', 'DD Mon') || ' – '
        || to_char(p_ends_at at time zone 'Asia/Kuala_Lumpur', 'DD Mon YYYY') || '. '
        || 'MIVO pays ' || v_share || '% of the discount and your shop pays ' || (100 - v_share)
        || '% on your items. Accept to join; if you reject, MIVO pays the full discount on your items '
        || 'but your shop is not featured in the campaign.',
      v_invited, 'campaign_invite', v_id);
  elsif p_commission_bump_rate is not null then
    perform public.platform_schedule_commission(null, p_commission_bump_rate, p_starts_at, p_ends_at,
      'Campaign "' || btrim(p_name) || '" — MIVO pays the full voucher discount', v_id);
  else
    perform public.platform_send_notice('New MIVO campaign: ' || btrim(p_name),
      coalesce(nullif(btrim(coalesce(p_description, '')), '') || E'\n\n', '')
        || 'MIVO pays the full discount of voucher ' || upper(btrim(p_voucher_code)) || '. No cost to your shop.',
      null, 'info', v_id);
  end if;
  return v_id;
end;
$$;

create or replace function public.seller_respond_campaign(p_campaign_id uuid, p_seller_id uuid, p_accept boolean)
returns void language plpgsql security definer set search_path = public as $$
declare c public.platform_campaigns%rowtype;
begin
  if not exists (select 1 from public.sellers where id = p_seller_id and owner_id = auth.uid()) then
    raise exception 'Not your shop';
  end if;
  select * into c from public.platform_campaigns where id = p_campaign_id;
  if not found or c.status <> 'active' then raise exception 'Campaign not found'; end if;
  if c.ends_at <= now() then raise exception 'This campaign has ended'; end if;
  if c.starts_at <= now() and p_accept = false
     and exists (select 1 from public.campaign_participants where campaign_id = p_campaign_id
                  and seller_id = p_seller_id and status = 'accepted') then
    raise exception 'The campaign has started; you can''t leave it now';
  end if;
  update public.campaign_participants
     set status = case when p_accept then 'accepted' else 'rejected' end, responded_at = now(), responded_by = auth.uid()
   where campaign_id = p_campaign_id and seller_id = p_seller_id;
  if not found then raise exception 'Your shop was not invited to this campaign'; end if;
end;
$$;

-- Who pays what, per shop, for orders that used the campaign voucher.
create or replace function public.campaign_settlement(p_campaign_id uuid)
returns table (seller_id uuid, shop_name text, participation text, orders bigint,
               discount numeric, seller_pays numeric, mivo_pays numeric)
language plpgsql stable security definer set search_path = public as $$
declare c public.platform_campaigns%rowtype;
begin
  select * into c from public.platform_campaigns where id = p_campaign_id;
  if not found then raise exception 'Campaign not found'; end if;
  return query
  with lines as (
    select so.seller_id,
           round(coalesce(o.discount_amount, 0) * so.subtotal / nullif(o.subtotal, 0), 2) as alloc
      from public.orders o
      join public.seller_orders so on so.order_id = o.id
     where upper(coalesce(o.voucher_code, '')) = c.voucher_code
       and o.payment_status in ('paid', 'partially_refunded')
       and o.created_at between c.starts_at and c.ends_at
  )
  select s.id, s.shop_name, coalesce(p.status, case when c.funding = 'platform' then 'platform-funded' else 'not invited' end),
         count(*)::bigint, sum(l.alloc),
         sum(case when c.funding = 'shared' and p.status = 'accepted'
                  then round(l.alloc * (100 - c.platform_share_pct) / 100, 2) else 0 end),
         sum(l.alloc) - sum(case when c.funding = 'shared' and p.status = 'accepted'
                  then round(l.alloc * (100 - c.platform_share_pct) / 100, 2) else 0 end)
    from lines l
    join public.sellers s on s.id = l.seller_id
    left join public.campaign_participants p on p.campaign_id = c.id and p.seller_id = s.id
   where public.is_superadmin() or s.owner_id = auth.uid()
   group by s.id, s.shop_name, p.status
   order by s.shop_name;
end;
$$;

create or replace function public.platform_campaigns_overview()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.mivo_require_superadmin();
  return (select coalesce(jsonb_agg(jsonb_build_object(
            'campaign', to_jsonb(c),
            'participants', (select coalesce(jsonb_agg(jsonb_build_object('seller_id', p.seller_id, 'shop', s.shop_name, 'status', p.status)), '[]'::jsonb)
                               from public.campaign_participants p join public.sellers s on s.id = p.seller_id where p.campaign_id = c.id))
          order by c.created_at desc), '[]'::jsonb)
          from public.platform_campaigns c);
end;
$$;

create or replace function public.platform_cancel_campaign(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.mivo_require_superadmin();
  update public.platform_campaigns set status = 'cancelled' where id = p_id;
  update public.commission_changes set status = 'cancelled' where campaign_id = p_id and status = 'scheduled';
  update public.commission_changes set ends_at = now() where campaign_id = p_id and status = 'active';
end;
$$;

-- ---------------------------------------------------------- permissions
do $$
declare f text;
begin
  foreach f in array array[
    'mivo_require_superadmin()', 'platform_send_notice(text, text, uuid[], text, uuid)', 'platform_notices_sent()',
    'seller_notices()', 'seller_unread_notices()', 'seller_mark_notice_read(uuid)',
    'platform_schedule_commission(uuid[], numeric, timestamptz, timestamptz, text, uuid)',
    'platform_cancel_commission(uuid)', 'mivo_apply_commission_changes()', 'platform_commission_overview()',
    'platform_create_campaign(text, text, text, timestamptz, timestamptz, text, numeric, numeric, uuid[])',
    'seller_respond_campaign(uuid, uuid, boolean)', 'campaign_settlement(uuid)',
    'platform_campaigns_overview()', 'platform_cancel_campaign(uuid)'] loop
    execute 'revoke all on function public.' || f || ' from public, anon';
    execute 'grant execute on function public.' || f || ' to authenticated';
  end loop;
end $$;

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';

